#include "cardputer_adv/lvgl_surface.hpp"
#include <cassert>
#include <fstream>
#include <filesystem>
#include "cardputer_adv/theme.hpp"
using namespace cardputer_adv;
std::array<lv_color_t,240*135> frame{};unsigned flushes=0;
void flush(lv_disp_drv_t* d,const lv_area_t* a,lv_color_t* p){++flushes;assert(a->x1>=0 && a->y1>=0 && a->x2<240 && a->y2<135);for(int y=a->y1;y<=a->y2;++y)for(int x=a->x1;x<=a->x2;++x)frame[y*240+x]=*p++;lv_disp_flush_ready(d);}
lv_color32_t rgba(lv_color_t c){lv_color32_t v;v.full=lv_color_to32(c);return v;}
void screenshot(const char* name="lvgl-chat"){std::filesystem::create_directories(".pio/ui-preview");std::ofstream out(std::string(".pio/ui-preview/")+name+".ppm",std::ios::binary);out<<"P6\n240 135\n255\n";for(auto c:frame){auto rgb=rgba(c);out.put(rgb.ch.red);out.put(rgb.ch.green);out.put(rgb.ch.blue);}}
int main(){static LvglSurface s;assert(s.begin(flush,nullptr,0));s.clear();s.setRGB(0x1924);s.fillRect(0,0,240,16);s.setRGB(0xffff);s.drawString(2,0,"RF OK SD OK 08:30 4.1V");s.drawString(2,16,"#0 LongFast");s.setRGB(0x1924);s.fillRect(0,32,240,16);s.setRGB(0x65ff);s.drawString(2,32,"> ANA: Olá, recebi!");s.setRGB(0x67f2);s.drawString(2,48,"  EU: Mensagem enviada");s.setRGB(0xffff);s.drawString(2,85,"Enter: escrever; dir: detalhe");s.drawString(2,101,"Enter: escrever (rascunho)");s.drawHorizontalLine(0,117,240);s.setRGB(0x65ff);s.fillRect(0,118,60,17);s.setColor(0);s.drawString(8,118,"CHAT");s.setRGB(0xffff);s.drawString(72,118,"NOS");s.drawString(120,118,"CANAIS");s.drawString(181,118,"AJUSTES");s.display(1);unsigned rx=0,tx=0;for(int y=32;y<48;++y)for(int x=0;x<240;++x){auto c=rgba(frame[y*240+x]);if(c.ch.blue>200 && c.ch.green>150 && c.ch.red<180)++rx;}for(int y=48;y<64;++y)for(int x=0;x<240;++x){auto c=rgba(frame[y*240+x]);if(c.ch.green>200 && c.ch.blue<200 && c.ch.red<180)++tx;}assert(rx>20 && tx>20);screenshot();assert(s.getStringWidth("Olá")>0 && s.getStringWidth("á")==s.getStringWidth("a"));for(unsigned n=0;n<100;++n){s.clear();s.setRGB(0xffff);s.drawString(2,16,"Teste de troca de tela");s.display(100+n*20);}auto rgb=rgba(frame[120*240+1]);assert(rgb.ch.red<50 && rgb.ch.green<50 && rgb.ch.blue<50);s.clear();s.setRGB(0xffff);s.drawString(2,16,"Teste de troca de tela");s.display(2200);auto before=flushes;
s.clear();s.setRGB(0xffff);s.drawString(2,16,"Teste de troca de tela");s.display(2300);assert(flushes==before);
s.clear();s.drawString(2,16,"Texto alterado");s.display(2400);assert(flushes>before);
lv_mem_monitor_t m;lv_mem_monitor(&m);assert(m.free_size>4096);
for(unsigned i=0;i<kThemeCount;++i){auto& t=theme(i);s.setBackground(t.background);s.clear();s.setRGB(t.panel);s.fillRect(0,0,240,16);s.setRGB(t.text);s.drawString(2,0,"RF OK SD OK 08:30 4.1V");s.drawString(2,16,t.name);s.setRGB(t.panel);s.fillRect(0,32,240,16);s.setRGB(t.received);s.drawString(2,32,"> ANA: Olá, recebi!");s.setRGB(t.sent);s.drawString(2,48,"  EU: Mensagem enviada");s.setRGB(t.text);s.drawString(2,85,"Enter: escrever; dir: detalhe");s.drawString(2,101,"Setas; Enter: salvar; Esc: sair");s.drawHorizontalLine(0,117,240);s.setRGB(t.active);s.fillRect(180,118,60,17);s.setRGB(t.active_text);s.drawString(181,118,"AJUSTES");s.setRGB(t.text);s.drawString(8,118,"CHAT");s.drawString(72,118,"NOS");s.drawString(120,118,"CANAIS");s.display(2500+i*100);auto bg=rgba(frame[110*240+239]);auto expected=rgba(lv_color_make(((t.background>>11)&31)*255/31,((t.background>>5)&63)*255/63,(t.background&31)*255/31));assert(bg.full==expected.full);char name[40];std::snprintf(name,sizeof(name),"m8-theme-%u",i);screenshot(name);}
lv_mem_monitor(&m);assert(m.free_size>4096);
}
